74	                .movePointRight(2)
75	                .divide(entryNet, 6, RoundingMode.HALF_UP);
76	        // 用精确乘法判定阈值，避免舍入影响“恰 2% 视为一致”的边界
77	        boolean exceeds = receiptNetKg.subtract(entryNet).abs().multiply(new BigDecimal("100"))
78	                .compareTo(entryNet.multiply(DEVIATION_THRESHOLD_PCT)) > 0;
79	        String result = exceeds ? "EXCEPTION" : "MATCH";
80	        String toStatus = exceeds ? ManifestStatus.EXCEPTION.name() : ManifestStatus.RECEIVED.name();
