36	     */
37	    private long registerInTransitManifest(String requestId) {
38	        long vehicleId = createVehicle();
39	        insertTare(vehicleId, new BigDecimal("8000.000"), clock.instant());
40	        return weighingService.registerEntry(entryCommand(requestId, vehicleId,
41	                new BigDecimal("13000.000"), null)).manifestId();
