44	    @Test
45	    void deviationExactlyTwoPercentIsConsistent() {
46	        long manifestId = registerInTransitManifest("REQ-E2-ENTRY");
47	
48	        // 进场 5000kg，回执 5100kg -> 偏差恰 2%，视为一致
49	        var result = receiptService.registerReceipt(manifestId, "REQ-E2-RECEIPT", new BigDecimal("5100.000"));
50	
51	        assertThat(result.result()).isEqualTo("MATCH");
52	        assertThat(result.deviationPct()).isEqualByComparingTo("2.000000");
53	        assertThat(manifestStatus(manifestId)).isEqualTo("RECEIVED");
54	    }
55	
56	    @Test
57	    void deviationAboveTwoPercentGoesToException() {
58	        long manifestId = registerInTransitManifest("REQ-G2-ENTRY");
59	
60	        // 回执 5101kg -> 偏差 2.02% > 2%，转异常核查
61	        var result = receiptService.registerReceipt(manifestId, "REQ-G2-RECEIPT", new BigDecimal("5101.000"));
62	
63	        assertThat(result.result()).isEqualTo("EXCEPTION");
64	        assertThat(result.deviationPct()).isEqualByComparingTo("2.020000");
65	        assertThat(manifestStatus(manifestId)).isEqualTo("EXCEPTION");
