72	
73	        var replay = receiptService.registerReceipt(manifestId, "REQ-RIDEM", new BigDecimal("5050.000"));
74	
75	        assertThat(replay.replayed()).isTrue();
76	        assertThat(replay.receiptId()).isEqualTo(first.receiptId());
